    {
      "id": "H0",
      "kind": "metric",
      "statement": "Total yellow taxi trips on Saturday 21 Dec 2024 were lower than the average of the other three Saturdays in December 2024 (7, 14, 28 Dec).",
      "support_if": "Target trips < baseline average trips by a meaningful margin (e.g., >5% drop).",
      "refute_if": "Target trips >= baseline average trips, or difference is negligible (<5%)."
    },
    {
      "id": "H1",
      "kind": "weather",
      "statement": "Snowfall on 21 Dec 2024 was substantially higher than on the other December Saturdays, and higher snowfall is associated with lower trip counts.",
      "support_if": "Snowfall on 21 Dec > 10 mm while other Saturdays had < 5 mm; and a negative correlation between daily snowfall and trips across the four Saturdays.",
      "refute_if": "Snowfall on 21 Dec was similar to other Saturdays, or trips did not decrease despite high snowfall."
    },
    {
      "id": "H2",
      "kind": "holiday",
      "statement": "A holiday on or near 21 Dec 2024 (e.g., Christmas observed) reduced trips independently of weather.",
      "support_if": "A federal or state holiday falls on 21 Dec or the adjacent Friday/Monday, and holiday dates show lower trips in historical data.",
      "refute_if": "No holiday on 21 Dec or adjacent weekdays; holiday table shows no holiday near that date."
    },
    {
      "id": "H3",
      "kind": "day_of_week",
      "statement": "The day-of-week pattern for Saturdays in December 2024 shows a secular trend (e.g., declining trips each Saturday) that explains the difference, not the snow.",
      "support_if": "Trips show a steady week-over-week decline across the four Saturdays (7, 14, 21, 28 Dec), making 21 Dec consistent with trend.",
      "refute_if": "Trips on 21 Dec are an outlier below the trend line defined by the other three Saturdays."
    },
    {
      "id": "H4",
      "kind": "fare_mix",
      "statement": "A shift in fare mix (e.g., fewer long-distance / airport trips) on 21 Dec reduced trip counts, possibly due to weather-related demand change.",
      "support_if": "Average trip distance and/or average total amount on 21 Dec are significantly lower than baseline Saturdays, indicating fewer long trips.",
      "refute_if": "Average trip distance and avg total amount on 21 Dec are in line with baseline Saturdays."
    },
    {
      "id": "H5",
      "kind": "zone_mix",
      "statement": "A change in pickup/dropoff zone mix (e.g., fewer Manhattan pickups) on 21 Dec reduced trips, but this cannot be tested with daily aggregates alone.",
      "support_if": "If zone-level data were available, a drop in high-volume zones (e.g., Manhattan) on 21 Dec vs baseline would support.",
      "refute_if": "Zone-level data not available in daily aggregate; hypothesis not testable with current tables."
    },
    {
      "id": "H6",
      "kind": "data_quality",
      "statement": "Missing or erroneous trip data for 21 Dec 2024 (or baseline Saturdays) creates a false appearance of a drop.",
      "support_if": "Trip count for 21 Dec is zero or implausibly low (<1000), or any baseline Saturday has missing data (NULL trips).",
      "refute_if": "All four Saturdays have plausible, non-null trip counts (>10k)."
    }
  ],
  "queries": [
    {
      "hypothesis_id": "H0",
      "purpose": "Return trip counts for each of the four December 2024 Saturdays (2024-12-07, 2024-12-14, 2024-12-21, 2024-12-28) to compute target vs baseline average.",
      "tables": ["whybot.yellow_daily"]
    },
    {
      "hypothesis_id": "H1",
      "purpose": "Return snowfall (snow_mm) for each of the four December 2024 Saturdays to compare 21 Dec snowfall vs others.",
      "tables": ["whybot.nyc_weather_daily", "whybot.yellow_daily"]
    },
    {
      "hypothesis_id": "H2",
      "purpose": "Check for any US holiday (federal or state) on 2024-12-21 or adjacent weekdays (2024-12-20, 2024-12-23) that could affect trips.",
      "tables": ["whybot.us_holidays"]
    },
    {
      "hypothesis_id": "H3",
      "purpose": "Return trip counts for all four December 2024 Saturdays to assess week-over-week trend (same as H0 query; reused).",
      "tables": ["whybot.yellow_daily"]
    },
    {
      "hypothesis_id": "H4",
      "purpose": "Return avg_trip_distance and avg_total_amount for each of the four December 2024 Saturdays to detect fare/distance mix shift on 21 Dec.",
      "tables": ["whybot.yellow_daily"]
    },
    {
      "hypothesis_id": "H6",
      "purpose": "Verify data quality: confirm all four Saturdays have non-null, plausible trip counts (>1000).",
      "tables": ["whybot.yellow_daily"]
    }
  ],
  "rationale": "The plan quantifies the metric change (H0) and tests five competing explanations: weather (H1), holiday (H2), secular Saturday trend (H3), fare/distance mix shift (H4), and data quality (H6). Zone mix (H5) is noted but not testable with daily aggregates. Each query is minimal, aggregated, and uses only catalog tables. The baseline uses the other three December Saturdays for a like-for-like weekday comparison. Memory lessons applied: use whybot.us_holidays not date_dim.d_holiday; join weather via yellow_daily trip_date; ensure aggregation in queries."
}

{
  "sql": "SELECT y.trip_date, y.trips, w.snow_mm, h.holiday_name FROM whybot.yellow_daily y JOIN whybot.nyc_weather_daily w ON w.obs_date = y.trip_date LEFT JOIN whybot.us_holidays h ON h.holiday_date = y.trip_date JOIN TPCDS_DB.date_dim d ON d.d_date = y.trip_date WHERE y.trip_date BETWEEN DATE '2024-12-01' AND DATE '2024-12-31' AND d.d_dow = 6 ORDER BY y.trip_date",
  "tables_used": [
    "whybot.yellow_daily",
    "whybot.nyc_weather_daily",
    "whybot.us_holidays",
    "TPCDS_DB.date_dim"
  ],
  "note": "Shows all Saturdays in December 2024 with snowfall, trips, and any holiday name for 21 Dec and adjacent weekdays."
}

